                             onClick={() => { setShowTemplates(true); showNotification('info', 'Loading Templates...'); }} 
                             className="p-2.5 text-slate-400 hover:text-white hover:bg-slate-800 rounded-xl transition-colors" 
                             title="Templates"
                           >
                             <Layers className="w-5 h-5" />
                           </button>
                       </div>

                       {/* Attached File Chip */}
                       {attachedFile && (
                           <div className="absolute top-[-40px] left-4 bg-slate-800 border border-slate-700 text-slate-300 px-3 py-1.5 rounded-lg flex items-center gap-2 text-xs shadow-lg animate-in fade-in slide-in-from-bottom-2">
                               <Paperclip className="w-3 h-3 text-vibrant-green" />
                               <span className="font-bold">{attachedFile.name}</span>
                               <button onClick={() => setAttachedFile(null)} className="hover:text-white"><X className="w-3 h-3"/></button>
                           </div>
                       )}

                       <textarea
                           value={input}
                           onChange={(e) => setInput(e.target.value)}
                           onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); executeWorkflowGeneration(input); } }}
                           placeholder="Speak or Type to Automate..."
                           className="flex-1 bg-transparent border-none outline-none text-white text-base placeholder:text-slate-500 min-h-[50px] max-h-32 py-3.5 resize-none custom-scrollbar"
                           rows={1}
                       />
                       <div className="flex items-center gap-2 pb-1.5 pr-1">
                           <button 
                               onClick={() => {
                                 if (!isListening) showNotification('info', 'Listening...');
                                 setIsListening(!isListening);
                               }} 
                               className={`p-3 rounded-full transition-all duration-300 ${
                                   isListening 
                                   ? 'bg-red-500 text-white animate-pulse shadow-[0_0_20px_rgba(239,68,68,0.4)] ring-4 ring-red-500/20' 
                                   : 'bg-slate-800 text-vibrant-orange border border-vibrant-orange/50 shadow-[0_0_15px_rgba(249,115,22,0.15)] hover:bg-vibrant-orange hover:text-white hover:shadow-[0_0_20px_rgba(249,115,22,0.4)]'
                               }`} 
                               title="Voice Input"
                           >
                               <Mic className="w-5 h-5" />
                           </button>
                           <button 
                             onClick={() => executeWorkflowGeneration(input)} 
                             disabled={(!input.trim() && !attachedFile) || isProcessing} 
                             className="p-3 bg-vibrant-green text-navy-900 rounded-xl hover:bg-emerald-400 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg shadow-green-900/20 transform active:scale-95"
                           >
                             <Send className="w-5 h-5" />
                           </button>
                       </div>
                   </div>
                   <div className="flex items-center justify-center gap-2 mt-3 opacity-40">
                       <ShieldCheck className="w-3 h-3 text-slate-400" />
                       <span className="text-[10px] text-slate-400 font-medium tracking-wide">Secure Enterprise Environment</span>
                   </div>
              </div>
           </div>
        )}
      </div>
    </div>
  );
};

