  const uiText = DEMO_TRANSLATIONS[language] || DEMO_TRANSLATIONS['English'];

  // Initialization & Mock Data
  useEffect(() => { 
      const mockHistory: WorkflowLog[] = Array.from({length: 15}).map((_, i) => ({
          id: `wk-${i}`,
          workflowName: i % 2 === 0 ? "Sync Shopify Orders to Zoho CRM" : "Automated Invoice Generation",
          agentId: i % 2 === 0 ? "operations" : "tax",
          timestamp: Date.now() - (i * 86400000),
          status: i === 0 ? 'Pending' : (i % 5 === 0 ? 'Failed' : 'Success'),
          timeSavedMinutes: Math.floor(Math.random() * 45) + 5,
          appsUsed: ['Shopify', 'Zoho Books'],
          executionTimeMs: Math.floor(Math.random() * 2000) + 500,
