          id: `wk-${i}`,
          workflowName: i % 2 === 0 ? "Sync Shopify Orders to Zoho CRM" : "Automated Invoice Generation",
          agentId: i % 2 === 0 ? "operations" : "tax",
          timestamp: Date.now() - (i * 86400000),
