  const [workflowHistory, setWorkflowHistory] = useState<WorkflowLog[]>([]);
  const [selectedWorkflowLog, setSelectedWorkflowLog] = useState<WorkflowLog | null>(null);
  const [notification, setNotification] = useState<{type: 'success' | 'error' | 'info', message: string} | null>(null);

  // New Filter States
  const [filterStatus, setFilterStatus] = useState<string>('All');
  const [filterDateRange, setFilterDateRange] = useState<{start: string, end: string}>({ start: '', end: '' });

  const [isListening, setIsListening] = useState(false);
  const [isTourOpen, setIsTourOpen] = useState(false);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  const activeAgent = useMemo(() => {
    return AGENT_CATALOG.find(a => a.id === activeAgentId) || AGENT_CATALOG[0];
  }, [activeAgentId]);

  const activeAgentTutorials = useMemo(() => {
      const specific = AGENT_VIDEO_TUTORIALS[activeAgentId];
      if (specific) return specific;
      // Default / Fallback tutorials if specific ones missing
