      if (!showWorkflowEditor) return;

      const interval = setInterval(() => {
          setActiveCollaborators(prev => prev.map(collab => {
              // Random chance to move to a different step
              if (Math.random() > 0.4) {
                  const randomStep = editorSteps[Math.floor(Math.random() * editorSteps.length)];
                  return { ...collab, currentStepId: randomStep.id };
              }
              // Random chance to deselect (simulate idle)
              if (Math.random() > 0.8) {
                  return { ...collab, currentStepId: null };
              }
              return collab;
          }));
      }, 3000); // Update every 3 seconds

      return () => clearInterval(interval);
  }, [showWorkflowEditor, editorSteps]);

  useEffect(() => {
    if (startTour) {
        setShowDashboard(false);
        setIsTourOpen(true);
    }
  }, [startTour]);

  // Handle Agent Switch - Context Reset
  useEffect(() => {
      setMessages([]);
      setShowDashboard(false);
      setShowWorkflowEditor(false);
      setEditingWorkflow(null);
  }, [activeAgentId]);

  useEffect(() => {
    if (initialPrompt && !isProcessing) {
        setShowDashboard(false);
        // Determine agent from prompt context roughly, default to sales
        if (initialPrompt.toLowerCase().includes('tax') || initialPrompt.toLowerCase().includes('gst')) setActiveAgentId('tax');
        else if (initialPrompt.toLowerCase().includes('hiring') || initialPrompt.toLowerCase().includes('resume')) setActiveAgentId('hr');
        else if (initialPrompt.toLowerCase().includes('meeting') || initialPrompt.toLowerCase().includes('schedule')) setActiveAgentId('meeting');
        else setActiveAgentId('sales');

        // Reset messages to clear previous context before new niche analysis
        setMessages([]);

        executeWorkflowGeneration(initialPrompt);
    }
  }, [initialPrompt]);

  useEffect(() => {
     if (messages.length > 0 && chatContainerRef.current) {
         chatContainerRef.current.scrollTo({ top: chatContainerRef.current.scrollHeight, behavior: 'smooth' });
     }
  }, [messages]);

  // Voice Input Logic
  useEffect(() => {
      if (isListening) {
          // Check for browser support
          const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;

          if (SpeechRecognition) {
              const recognition = new SpeechRecognition();
              recognition.lang = language === 'Hindi' ? 'hi-IN' : language === 'Bengali' ? 'bn-IN' : 'en-US';

              recognition.onresult = (event: any) => {
                  const transcript = event.results[0][0].transcript;
                  setInput(prev => prev + (prev ? ' ' : '') + transcript);
                  setIsListening(false);
                  showNotification('success', 'Voice input captured');
              };

              recognition.onerror = () => {
                 setIsListening(false);
                 showNotification('error', 'Microphone access denied or error.');
              };

              recognition.onend = () => setIsListening(false);

              try {
                  recognition.start();
              } catch(e) {
                  setIsListening(false);
                  // fallback to simulation
                  simulateVoiceInput();
              }

              return () => {
                  try { recognition.stop(); } catch(e){}
              };
          } else {
              // Fallback Simulation
              simulateVoiceInput();
          }
      }
  }, [isListening, attachedFile, language]);

  const simulateVoiceInput = () => {
      const textToType = attachedFile 
          ? "Analyze this uploaded document and extract the key financial metrics." 
          : "Create a new workflow to sync my leads from Facebook to Zoho CRM.";

      const timer = setTimeout(() => {
          setInput(textToType);
          setIsListening(false);
          showNotification('success', 'Voice simulation captured');
      }, 2500);
      return () => clearTimeout(timer);
  };

  const showNotification = (type: 'success' | 'error' | 'info', message: string) => {
      setNotification({ type, message });
      setTimeout(() => setNotification(null), 3000);
  };

  const handleFileUpload = () => {
      // Trigger the hidden file input
      fileInputRef.current?.click();
      showNotification('info', 'Select a file to upload...');
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          showNotification('info', `Uploading ${file.name}...`);
          // Simulate network delay for upload
          setTimeout(() => {
              setAttachedFile({ name: file.name, type: file.type });
              showNotification('success', 'File attached successfully');
          }, 1500);
      }
  };

  const toggleAppConnection = (appId: string) => {
      if (connectedApps.includes(appId)) {
          if (connectedApps.length <= 1) {
              showNotification('error', 'At least 1 app must be connected.');
              return;
          }
          setConnectedApps(prev => prev.filter(id => id !== appId));
          showNotification('info', 'App disconnected');
      } else {
          if (connectedApps.length >= 5) {
              showNotification('error', 'Maximum 5 apps can be connected.');
              return;
          }
          setConnectedApps(prev => [...prev, appId]);
          showNotification('success', 'App connected successfully');
      }
  };

  const updateEditorSteps = (newSteps: EditorStep[]) => {
      // Create a new history entry
      const newHistory = history.slice(0, currentHistoryIndex + 1);
      newHistory.push(newSteps);
      setHistory(newHistory);
      setCurrentHistoryIndex(newHistory.length - 1);
      setEditorSteps(newSteps);
  };

  const handleUndo = () => {
      if (currentHistoryIndex > 0) {
          const prevIndex = currentHistoryIndex - 1;
          setCurrentHistoryIndex(prevIndex);
          setEditorSteps(history[prevIndex]);
          showNotification('info', 'Undo successful');
      }
  };

  const handleRedo = () => {
      if (currentHistoryIndex < history.length - 1) {
          const nextIndex = currentHistoryIndex + 1;
          setCurrentHistoryIndex(nextIndex);
