                 </div>

                 {/* Dashboard Content */}
                 <div className="flex-1 bg-[#020617] p-8 overflow-y-auto">
                     {renderDashboardView()}
                 </div>
             </div>
        ) : (
            // Chat Interface
            <div className="flex-1 flex flex-col relative bg-[#020617]">
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-slate-800 bg-[#0B1120]/80 backdrop-blur-sm z-20">
                    <div className="flex items-center gap-4">
                        <div className="relative group">
                             <button 
                                 id="tour-agent-sidebar"
                                 onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                                 className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-white transition-colors border border-slate-700"
                             >
                                 <div className={`p-1.5 rounded ${activeAgent.bgColor} ${activeAgent.color}`}>
                                     <activeAgent.icon className="w-4 h-4" />
                                 </div>
                                 <span className="text-sm font-bold hidden sm:inline">{activeAgent.name}</span>
                                 <ChevronDown className="w-4 h-4 text-slate-500" />
                             </button>
                             {/* Agent Dropdown */}
                             {isMobileMenuOpen && (
                                 <div className="absolute top-full left-0 mt-2 w-64 bg-[#0f172a] border border-slate-700 rounded-xl shadow-2xl overflow-hidden z-50 animate-in fade-in slide-in-from-top-2">
                                     <div className="max-h-[300px] overflow-y-auto py-1">
                                         {AGENT_CATALOG.map(agent => (
                                             <button
                                                 key={agent.id}
                                                 onClick={() => { setActiveAgentId(agent.id); setIsMobileMenuOpen(false); }}
                                                 className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-800 transition-colors text-left ${activeAgentId === agent.id ? 'bg-slate-800/80' : ''}`}
                                             >
                                                 <div className={`p-1.5 rounded ${agent.bgColor} ${agent.color}`}>
                                                     <agent.icon className="w-4 h-4" />
                                                 </div>
                                                 <div>
                                                     <div className={`text-xs font-bold ${activeAgentId === agent.id ? 'text-white' : 'text-slate-300'}`}>{agent.name}</div>
                                                     <div className="text-[10px] text-slate-500 truncate w-32">{agent.role}</div>
                                                 </div>
                                                 {activeAgentId === agent.id && <Check className="w-3 h-3 text-vibrant-green ml-auto" />}
                                             </button>
                                         ))}
                                     </div>
                                 </div>
                             )}
                        </div>

                        <div className="h-6 w-px bg-slate-800 hidden sm:block"></div>

                        <div className="flex items-center gap-2">
                             <button onClick={() => setShowTemplates(true)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors" title="Templates">
                                 <Layers className="w-4 h-4" />
                             </button>
                             <button onClick={() => setShowIntegrations(true)} className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors" title="Apps">
                                 <LayoutGrid className="w-4 h-4" />
                             </button>
                             <button onClick={() => setShowVideoLibrary(!showVideoLibrary)} className={`p-2 rounded-lg transition-colors ${showVideoLibrary ? 'text-vibrant-orange bg-orange-900/20' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`} title="Tutorials">
                                 <Video className="w-4 h-4" />
                             </button>
                        </div>
                    </div>

                    <div className="flex items-center gap-3">
                         <button 
                             id="tour-dashboard-btn"
                             onClick={() => setShowDashboard(true)}
                             className="hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 hover:text-white border border-slate-700 transition-all text-xs font-bold"
                         >
                             <LayoutDashboard className="w-4 h-4" />
                             Dashboard
                         </button>
                         <button 
                             onClick={handleCreateNewAgent}
                             className="p-2 bg-vibrant-green/10 text-vibrant-green hover:bg-vibrant-green hover:text-navy-900 rounded-lg transition-all border border-vibrant-green/20"
                             title="New Chat"
                         >
                             <Plus className="w-4 h-4" />
                         </button>
                    </div>
                </div>

                {/* Main Chat Area */}
                <div className="flex-1 overflow-hidden relative flex">
                    {/* Tutorial Sidebar (Conditional) */}
                    {showVideoLibrary && (
                        <div className="w-64 bg-[#0B1120] border-r border-slate-800 overflow-y-auto animate-in slide-in-from-left duration-300 hidden md:block">
                            <div className="p-4">
                                <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-4">Video Tutorials</h3>
                                <div className="space-y-4">
                                    {activeAgentTutorials.map((video: any, i: number) => (
                                        <div key={i} className="group cursor-pointer">
                                            <div className="relative aspect-video rounded-lg overflow-hidden mb-2 border border-slate-700 group-hover:border-vibrant-orange/50 transition-colors">
                                                <img src={video.thumb} alt={video.title} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" />
                                                <div className="absolute inset-0 flex items-center justify-center">
                                                    <div className="w-8 h-8 rounded-full bg-black/50 flex items-center justify-center backdrop-blur-sm group-hover:bg-vibrant-orange group-hover:scale-110 transition-all">
                                                        <Play className="w-3 h-3 text-white fill-white ml-0.5" />
                                                    </div>
                                                </div>
                                                <div className="absolute bottom-1 right-1 bg-black/70 px-1 rounded text-[9px] font-bold text-white">{video.duration}</div>
                                            </div>
                                            <div className="text-xs font-bold text-slate-300 group-hover:text-white line-clamp-2 leading-tight">{video.title}</div>
                                            <div className="text-[10px] text-slate-500 mt-1">{video.lang}</div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Messages Container */}
                    <div 
                        ref={chatContainerRef}
                        className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6 scroll-smooth"
                    >
                        {messages.length === 0 ? (
                            <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-0 animate-in fade-in zoom-in duration-500">
                                <div className={`w-20 h-20 rounded-3xl ${activeAgent.bgColor} ${activeAgent.color} flex items-center justify-center mb-6 shadow-2xl shadow-${activeAgent.color.split('-')[1]}-500/20`}>
                                    <activeAgent.icon className="w-10 h-10" />
                                </div>
                                <h2 className="text-3xl font-bold text-white mb-2">{uiText.welcome} <span className="text-transparent bg-clip-text bg-gradient-to-r from-white to-slate-400">{activeAgent.name}</span></h2>
                                <p className="text-slate-400 max-w-md mb-8 text-sm">
                                    I can help you {activeAgent.role.toLowerCase()}. Try asking me to create a workflow, analyze data, or connect your apps.
                                </p>

                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full max-w-2xl">
                                    {AGENT_TEMPLATES.filter(t => t.agent === activeAgentId).slice(0, 4).map((tpl, i) => (
                                        <button 
                                            key={i}
                                            onClick={() => handleTemplateClick(tpl)}
                                            className="p-4 rounded-xl bg-slate-900/50 border border-slate-800 hover:bg-slate-800 hover:border-slate-600 transition-all text-left group"
                                        >
                                            <div className="flex items-center gap-3 mb-2">
                                                <div className="p-1.5 bg-slate-800 rounded-lg text-slate-400 group-hover:text-white group-hover:bg-slate-700 transition-colors">
                                                    <tpl.icon className="w-4 h-4" />
                                                </div>
                                                <span className="text-xs font-bold text-slate-300 group-hover:text-white">{tpl.title}</span>
                                            </div>
                                            <div className="text-[10px] text-slate-500 line-clamp-2 pl-9">{tpl.desc}</div>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        ) : (
                            messages.map((msg, idx) => (
                                <div key={idx} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-2`}>
                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${
                                        msg.role === 'user' 
                                        ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' 
                                        : `${activeAgent.bgColor} ${activeAgent.color} border border-white/5`
                                    }`}>
                                        {msg.role === 'user' ? (currentUser ? currentUser.name.charAt(0) : <UserIcon className="w-4 h-4" />) : <activeAgent.icon className="w-4 h-4" />}
                                    </div>

                                    <div className={`max-w-[85%] sm:max-w-[75%] space-y-2 ${msg.role === 'user' ? 'items-end flex flex-col' : ''}`}>
                                        {/* Bubble */}
                                        <div className={`rounded-2xl p-4 text-sm leading-relaxed shadow-md ${
                                            msg.role === 'user' 
                                            ? 'bg-indigo-600 text-white rounded-tr-none' 
                                            : 'bg-slate-800/80 text-slate-200 border border-slate-700/50 rounded-tl-none backdrop-blur-sm'
                                        }`}>
                                            {msg.text.split('\n').map((line, i) => (
                                                <p key={i} className={i > 0 ? 'mt-2' : ''}>{line}</p>
                                            ))}
                                        </div>

                                        {/* Workflow Card (if present) */}
                                        {msg.workflowData && (
                                            <div className="w-full bg-[#0f172a] rounded-2xl border border-slate-700 overflow-hidden shadow-2xl mt-4 animate-in zoom-in-95 duration-500">
                                                {/* Card Header */}
                                                <div className="p-4 border-b border-slate-800 bg-slate-900/50 flex justify-between items-center">
                                                    <div className="flex items-center gap-3">
                                                        <div className="p-1.5 bg-green-500/10 rounded-lg border border-green-500/20">
                                                            <GitBranch className="w-4 h-4 text-vibrant-green" />
                                                        </div>
                                                        <div>
                                                            <div className="text-sm font-bold text-white">{msg.workflowData.workflow_name}</div>
                                                            <div className="text-[10px] text-slate-500">Auto-Generated Agentic Flow</div>
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center gap-2">
                                                        <button 
                                                            className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-800 rounded transition-colors"
                                                            onClick={() => handleExecuteWorkflow(null as any, msg.workflowData!)}
                                                            title="Run Now"
                                                        >
                                                            <Play className="w-4 h-4" />
                                                        </button>
                                                        <button className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-800 rounded transition-colors" title="Export JSON">
                                                            <Download className="w-4 h-4" />
                                                        </button>
                                                    </div>
                                                </div>

                                                {/* Flow Visualization (Simplified) */}
                                                <div className="p-6 relative">
                                                    {/* Vertical Line */}
                                                    <div className="absolute left-8 top-6 bottom-6 w-0.5 bg-slate-800"></div>

                                                    <div className="space-y-6 relative z-10">
                                                        {/* Trigger Node */}
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-8 h-8 rounded-full bg-slate-900 border-2 border-orange-500 flex items-center justify-center shadow-[0_0_15px_rgba(249,115,22,0.3)]">
                                                                <Zap className="w-4 h-4 text-orange-500" />
                                                            </div>
                                                            <div className="flex-1 bg-slate-800/50 p-3 rounded-xl border border-slate-700/50">
                                                                <div className="text-[10px] font-bold text-orange-400 uppercase">Trigger</div>
                                                                <div className="text-sm font-bold text-slate-200">{msg.workflowData.trigger.type}</div>
                                                                <div className="text-xs text-slate-500 mt-0.5">{msg.workflowData.trigger.frequency}</div>
                                                            </div>
                                                        </div>

                                                        {/* Action Nodes */}
                                                        {msg.workflowData.actions.map((action, i) => (
                                                            <div key={i} className="flex items-center gap-4">
                                                                <div className="w-8 h-8 rounded-full bg-slate-900 border-2 border-blue-500 flex items-center justify-center shadow-[0_0_15px_rgba(59,130,246,0.3)]">
                                                                    <div className="text-[10px] font-bold text-blue-500">{i + 1}</div>
                                                                </div>
                                                                <div className="flex-1 bg-slate-800/50 p-3 rounded-xl border border-slate-700/50 flex items-center justify-between group">
                                                                    <div>
                                                                        <div className="flex items-center gap-2 mb-1">
                                                                            <span className="text-[10px] font-bold text-blue-400 uppercase bg-blue-500/10 px-1.5 py-0.5 rounded">{action.app}</span>
                                                                            {action.auto_integration && <span className="text-[10px] text-vibrant-green flex items-center gap-0.5"><Check className="w-3 h-3" /> Auto</span>}
                                                                        </div>
                                                                        <div className="text-sm font-bold text-slate-200">{action.action_type}</div>
                                                                        <div className="text-xs text-slate-500 mt-0.5 line-clamp-1">{action.instructions}</div>
                                                                    </div>
                                                                    <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                                                                         <Settings className="w-4 h-4 text-slate-500 hover:text-white cursor-pointer" />
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        ))}

                                                        {/* Output Node */}
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-8 h-8 rounded-full bg-slate-900 border-2 border-vibrant-green flex items-center justify-center shadow-[0_0_15px_rgba(16,185,129,0.3)]">
                                                                <Check className="w-4 h-4 text-vibrant-green" />
                                                            </div>
                                                            <div className="flex-1 bg-green-900/10 p-3 rounded-xl border border-green-500/20">
                                                                <div className="text-[10px] font-bold text-vibrant-green uppercase">Final Output</div>
                                                                <div className="text-sm font-bold text-slate-200">{msg.workflowData.final_output.delivery_method}</div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>

                                                {/* Action Footer */}
                                                <div className="p-4 bg-slate-900 border-t border-slate-800 flex gap-3">
                                                    <button 
                                                        onClick={(e) => handleExecuteWorkflow(e, msg.workflowData!)}
                                                        className="flex-1 bg-vibrant-green hover:bg-emerald-500 text-navy-900 font-bold py-2.5 rounded-lg text-sm transition-all shadow-lg shadow-green-900/20 flex items-center justify-center gap-2"
                                                    >
                                                        <Play className="w-4 h-4" /> Run Workflow
                                                    </button>
                                                    <button 
                                                        onClick={() => {
                                                            // Mock converting to editable log
                                                            const mockLog: WorkflowLog = {
                                                                id: 'draft-1',
                                                                workflowName: msg.workflowData!.workflow_name,
                                                                agentId: activeAgentId,
                                                                timestamp: Date.now(),
                                                                status: 'Pending',
                                                                timeSavedMinutes: 0,
                                                                appsUsed: msg.workflowData!.actions.map(a => a.app),
                                                                roi: 0
                                                            };
                                                            handleEditWorkflow(mockLog);
                                                        }}
                                                        className="px-4 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-lg text-sm border border-slate-700 transition-colors flex items-center gap-2"
                                                    >
                                                        <Edit className="w-4 h-4" /> Customize
                                                    </button>
                                                </div>
                                            </div>
                                        )}

                                        <div className={`text-[10px] text-slate-500 ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                                            {new Date(msg.timestamp || Date.now()).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                        {isProcessing && (
                            <div className="flex gap-4 animate-in fade-in slide-in-from-bottom-2">
                                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${activeAgent.bgColor} ${activeAgent.color} border border-white/5`}>
                                    <activeAgent.icon className="w-4 h-4 animate-pulse" />
                                </div>
                                <div className="bg-slate-800/80 p-4 rounded-2xl rounded-tl-none border border-slate-700/50 backdrop-blur-sm flex items-center gap-3">
                                    <div className="flex gap-1">
                                        <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                        <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                        <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
                                    </div>
                                    <span className="text-xs text-slate-400 font-medium">Thinking...</span>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Input Area */}
                    <div className="absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-[#020617] via-[#020617] to-transparent pt-10">
                         {/* Attachment Preview */}
                         {attachedFile && (
                             <div className="mx-2 mb-2 inline-flex items-center gap-2 bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-700 animate-in slide-in-from-bottom-2 fade-in">
                                 <Paperclip className="w-3 h-3 text-vibrant-green" />
                                 <span className="text-xs text-white truncate max-w-[200px]">{attachedFile.name}</span>
                                 <button onClick={() => setAttachedFile(null)} className="ml-1 text-slate-500 hover:text-white"><X className="w-3 h-3" /></button>
                             </div>
                         )}

                         <div className="relative flex items-end gap-2 bg-[#0B1120] border border-slate-700 p-2 rounded-2xl shadow-2xl transition-colors focus-within:border-slate-500" id="tour-chat-input">
                             <input 
                                 type="file" 
                                 ref={fileInputRef} 
                                 className="hidden" 
                                 onChange={handleFileSelect} 
                             />

                             <button 
                                 onClick={handleFileUpload}
                                 className="p-3 text-slate-400 hover:text-white hover:bg-slate-800 rounded-xl transition-colors shrink-0"
                                 title="Attach File"
                             >
                                 <Paperclip className="w-5 h-5" />
                             </button>

                             <textarea
                                 value={input}
                                 onChange={(e) => setInput(e.target.value)}
                                 onKeyDown={(e) => {
                                     if (e.key === 'Enter' && !e.shiftKey) {
                                         e.preventDefault();
                                         executeWorkflowGeneration(input);
                                     }
                                 }}
                                 placeholder={isListening ? "Listening..." : "Describe a workflow or task..."}
                                 className="flex-1 bg-transparent border-none text-white placeholder:text-slate-500 focus:ring-0 resize-none max-h-32 py-3 text-sm"
                                 rows={1}
                             />

                             <div className="flex items-center gap-2 shrink-0">
                                 <button 
                                     onClick={() => setIsListening(!isListening)}
                                     className={`p-3 rounded-xl transition-all duration-300 ${isListening ? 'bg-red-500/20 text-red-500 animate-pulse' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
                                     title="Voice Input"
                                 >
                                     {isListening ? <Mic2 className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
                                 </button>
                                 <button 
                                     onClick={() => executeWorkflowGeneration(input)}
                                     disabled={!input.trim() && !attachedFile}
                                     className="p-3 bg-white text-navy-900 rounded-xl hover:bg-slate-200 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform active:scale-95 shadow-lg shadow-white/10"
                                 >
                                     <Send className="w-5 h-5 fill-current" />
                                 </button>
                             </div>
                         </div>
                         <div className="text-center mt-2">
                             <p className="text-[10px] text-slate-600">
                                 AI can make mistakes. Review generated workflows before executing.
                             </p>
                         </div>
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* Global Toast Notification */}
      {notification && (
          <div className={`fixed top-4 right-4 z-[150] px-4 py-3 rounded-xl shadow-2xl border flex items-center gap-3 animate-in slide-in-from-top-4 fade-in duration-300 ${
              notification.type === 'success' ? 'bg-green-500/10 border-green-500/20 text-green-400' : 
              notification.type === 'error' ? 'bg-red-500/10 border-red-500/20 text-red-400' : 
              'bg-blue-500/10 border-blue-500/20 text-blue-400'
          }`}>
              {notification.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : notification.type === 'error' ? <AlertCircle className="w-5 h-5" /> : <Info className="w-5 h-5" />}
              <span className="text-sm font-bold">{notification.message}</span>
          </div>
      )}
    </div>
  );
};
